function updateActionMarkers(id){const chart=document.getElementById(id),sourceIndex=chart.data.findIndex(function(trace){return trace.meta&&trace.meta.seriesKey==='ppo'});if(sourceIndex<0)return Promise.resolve();const sourceDates=traceDates(chart,sourceIndex),sourceValues=numericArray(fullTrace(chart,sourceIndex).y),lookup=new Map();for(let i=0;i<Math.min(sourceDates.length,sourceValues.length);i+=1)lookup.set(isoDate(sourceDates[i]),sourceValues[i]);const indexes=[],series=[];chart.data.forEach(function(trace,index){if(!(trace.meta&&trace.meta.actionMarkers))return;const xs=traceDates(chart,index);indexes.push(index);series.push(xs.map(function(date){const value=lookup.get(isoDate(date));return Number.isFinite(Number(value))?Number(value):null}))});return indexes.length?Plotly.restyle(chart,{y:series},indexes):Promise.resolve()}
function rebaseDrawdownChart(start){const chart=document.getElementById('drawdown-chart'),wealthSeries=chart._windowOriginalWealth||[],indexes=[],series=[];chart.data.forEach(function(trace,index){const wealth=wealthSeries[index];if(!wealth||!wealth.length)return;const xs=traceDates(chart,index);let runningPeak=-Infinity;const next=wealth.map(function(value,i){const date=isoDate(xs[i]),number=Number(value);if(date<start||!Number.isFinite(number)||number<=0)return null;runningPeak=Math.max(runningPeak,number);return Math.round((number/runningPeak-1)*10000)/100});indexes.push(index);series.push(next)});return indexes.length?Plotly.restyle(chart,{y:series},indexes):Promise.resolve()}
function updateMddMarkers(id,start,end,mode){const chart=document.getElementById(id),original=chart._windowOriginalY||[],wealthSeries=chart._windowOriginalWealth||[],indexes=[],xSeries=[],ySeries=[],customSeries=[];chart.data.forEach(function(marker,markerIndex){if(!(marker.meta&&marker.meta.mddRole))return;const sourceIndex=chart.data.findIndex(function(trace){return trace.meta&&trace.meta.seriesKey===marker.meta.sourceKey});if(sourceIndex<0)return;const xs=traceDates(chart,sourceIndex),raw=mode==='drawdown'?wealthSeries[sourceIndex]:original[sourceIndex],current=numericArray(fullTrace(chart,sourceIndex).y);if(!raw||!raw.length)return;let runningPeak=-Infinity,runningPeakIndex=-1,bestDrawdown=0,bestPeak=-1,bestTrough=-1;for(let i=0;i<Math.min(xs.length,raw.length);i+=1){const date=isoDate(xs[i]),number=Number(raw[i]);if(date<start||date>end||!Number.isFinite(number))continue;const wealth=mode==='returns'?1+number/100:number;if(!Number.isFinite(wealth)||wealth<=0)continue;if(wealth>runningPeak){runningPeak=wealth;runningPeakIndex=i}const drawdown=wealth/runningPeak-1;if(bestTrough<0||drawdown<bestDrawdown){bestDrawdown=drawdown;bestPeak=runningPeakIndex;bestTrough=i}}if(bestTrough<0||bestPeak<0)return;const peakDate=isoDate(xs[bestPeak]),troughDate=isoDate(xs[bestTrough]),peakValue=Number(current[bestPeak]),troughValue=Number(current[bestTrough]),magnitude=Math.abs(bestDrawdown)*100;indexes.push(markerIndex);xSeries.push([xs[bestPeak],xs[bestTrough]]);ySeries.push([peakValue,troughValue]);customSeries.push([["起点",peakDate,troughDate,magnitude],["终点",peakDate,troughDate,magnitude]])});return indexes.length?Plotly.restyle(chart,{x:xSeries,y:ySeries,customdata:customSeries},indexes):Promise.resolve()}
function syncMddMarkerVisibility(chart){if(chart._mddVisibilitySync)return Promise.resolve();const indexes=[],visible=[];chart.data.forEach(function(marker,index){if(!(marker.meta&&marker.meta.mddRole))return;const source=chart.data.find(function(trace){return trace.meta&&trace.meta.seriesKey===marker.meta.sourceKey});if(!source)return;const next=source.visible!==false&&source.visible!=='legendonly';if(marker.visible!==next){indexes.push(index);visible.push(next)}});if(!indexes.length)return Promise.resolve();chart._mddVisibilitySync=true;return Plotly.restyle(chart,{visible:visible},indexes).finally(function(){chart._mddVisibilitySync=false})}
