function initializeMddMarkerVisibility(){['performance-chart','returns-chart','drawdown-chart'].forEach(function(id){const chart=document.getElementById(id);if(!chart)return;chart.on('plotly_restyle',function(event){const update=event&&event[0];if(update&&Object.prototype.hasOwnProperty.call(update,'visible'))scheduleMddMarkerVisibility(chart)});syncMddMarkerVisibility(chart)})}
function traceAxis(trace){return(trace&&trace.yaxis)||'y'}
function clearHoverPoint(chart){const indexes=[];chart.data.forEach(function(trace,index){if(trace.meta&&trace.meta.hoverPoint)indexes.push(index)});if(indexes.length)Plotly.restyle(chart,{x:indexes.map(function(){return[]}),y:indexes.map(function(){return[]})},indexes)}
function showHoverPoint(chart,event){const points=Array.from(event.points||[]).filter(function(point){const trace=point.data,meta=(trace&&trace.meta)||{};return trace&&String(trace.mode||'').includes('lines')&&meta.windowRole!=='cash'&&!meta.mddRole&&!meta.hoverPoint&&!meta.actionMarkers});const hoverIndexes=[];chart.data.forEach(function(trace,index){if(trace.meta&&trace.meta.hoverPoint)hoverIndexes.push(index)});if(!hoverIndexes.length)return;if(!points.length){clearHoverPoint(chart);return}hoverIndexes.forEach(function(index){const axis=traceAxis(chart.data[index]),matches=points.filter(function(point){return traceAxis(point.data)===axis}),xs=matches.map(function(point){return point.x}),ys=matches.map(function(point){return point.y}),colors=matches.map(function(point){return point.data.line&&point.data.line.color?point.data.line.color:'#1474a8'});Plotly.restyle(chart,{x:[xs],y:[ys],'marker.color':[colors]},[index])})}
function initializeHoverPoints(){['performance-chart','returns-chart','drawdown-chart','momentum-chart','portfolio-attribution-0','strategy-diagnostic-2'].forEach(function(id){const chart=document.getElementById(id);if(!chart)return;const handler=function(event){showHoverPoint(chart,event)};chart.on('plotly_hover',handler);chart.on('plotly_click',handler);chart.on('plotly_unhover',function(){clearHoverPoint(chart)})})}

function visibleRange(chart,start,end,traceAxis,includeZero){let low=Infinity,high=-Infinity;chart.data.forEach(function(trace,index){if(trace.visible===false||trace.visible==='legendonly'||(trace.yaxis||'y')!==traceAxis||(trace.meta&&trace.meta.windowRole==='cash'))return;const xs=traceDates(chart,index),ys=numericArray(fullTrace(chart,index).y);for(let i=0;i<Math.min(xs.length,ys.length);i+=1){const date=isoDate(xs[i]),value=Number(ys[i]);if(date>=start&&date<=end&&Number.isFinite(value)){low=Math.min(low,value);high=Math.max(high,value)}}});if(!Number.isFinite(low)||!Number.isFinite(high))return null;if(includeZero){low=Math.min(low,0);high=Math.max(high,0)}let span=high-low;if(span<=0)span=Math.max(Math.abs(high)*0.08,1);const pad=span*0.06;return[low-pad,high+pad]}
function yAxisUpdates(chart,start,end){const update={};if(chart.id==='performance-chart'){const range=visibleRange(chart,start,end,'y',false);if(range)update['yaxis.range']=range;update['yaxis2.range']=[0,100]}else if(chart.id==='returns-chart'){const range=visibleRange(chart,start,end,'y',true);if(range)update['yaxis.range']=range;update['yaxis.title.text']=returnsLogScale?'对数累计收益 100×ln(1+R)':'累计收益';update['yaxis.ticksuffix']='%';update['yaxis2.range']=[0,100]}else if(chart.id==='drawdown-chart'){const range=visibleRange(chart,start,end,'y',true);if(range)update['yaxis.range']=range}else if(chart.id==='allocation-chart'){update['yaxis.range']=[0,102]}else if(chart.id==='momentum-chart'){const range=visibleRange(chart,start,end,'y',true);if(range)update['yaxis.range']=range}else if(chart.id==='portfolio-attribution-0'){const range=visibleRange(chart,start,end,'y',true);if(range)update['yaxis.range']=range}else if(chart.id==='strategy-diagnostic-2'){const top=visibleRange(chart,start,end,'y',true),bottom=visibleRange(chart,start,end,'y2',true);if(top)update['yaxis.range']=top;if(bottom)update['yaxis2.range']=bottom}return update}
function applyDateRange(job){const entries=targetTimeCharts(job),targetIds=new Set(entries.map(function(entry){return entry[0]}));syncingDates=true;['performance-chart','returns-chart','drawdown-chart','momentum-chart','portfolio-attribution-0','strategy-diagnostic-2'].forEach(function(id){if(targetIds.has(id))clearHoverPoint(document.getElementById(id))});const dataUpdates=[];if(targetIds.has('performance-chart'))dataUpdates.push(rebaseChart('performance-chart',job.start,'performance'));if(targetIds.has('returns-chart'))dataUpdates.push(rebaseChart('returns-chart',job.start,'returns'));if(targetIds.has('drawdown-chart'))dataUpdates.push(rebaseDrawdownChart(job.start));if(targetIds.has('portfolio-attribution-0'))dataUpdates.push(rebaseAttributionChart(job.start));return Promise.all(dataUpdates).then(function(){const markerUpdates=[];if(targetIds.has('performance-chart'))markerUpdates.push(updateActionMarkers('performance-chart'),updateMddMarkers('performance-chart',job.start,job.end,'performance'));if(targetIds.has('returns-chart'))markerUpdates.push(updateActionMarkers('returns-chart'),updateMddMarkers('returns-chart',job.start,job.end,'returns'));if(targetIds.has('drawdown-chart'))markerUpdates.push(updateMddMarkers('drawdown-chart',job.start,job.end,'drawdown'));return Promise.all(markerUpdates)}).then(function(){return Promise.all(entries.map(function(entry){const chart=document.getElementById(entry[0]),update=yAxisUpdates(chart,job.start,job.end),ticks=chartDateTicks(chart,job.start,job.end);update[entry[1]+'.range']=[job.start,job.end];update[entry[1]+'.autorange']=false;update[entry[1]+'.tickmode']='array';update[entry[1]+'.tickvals']=ticks.values;update[entry[1]+'.ticktext']=ticks.text;update[entry[1]+'.tickangle']=0;if(chart.id==='strategy-diagnostic-2')update['xaxis.range']=[job.start,job.end];return Plotly.relayout(chart,update)}))}).then(function(){return Promise.all(['performance-chart','returns-chart','drawdown-chart'].filter(function(id){return targetIds.has(id)}).map(function(id){return syncMddMarkerVisibility(document.getElementById(id))}))}).finally(function(){syncingDates=false})}
function flushPendingRange(){rangeFrame=null;if(rangeApplying||!pendingRange)return;const job=pendingRange;pendingRange=null;rangeApplying=true;applyDateRange(job).finally(function(){rangeApplying=false;if(pendingRange&&rangeFrame===null)rangeFrame=requestAnimationFrame(flushPendingRange)})}
function normalizedRange(start,end,sourceId){let a=clampDate(start),b=clampDate(end);if(a>b){if(sourceId==='global-end')a=b;else b=a}return{start:a,end:b,sourceId:sourceId}}
function storeRange(job){job.independent=Boolean(job.sourceId&&independentCharts.has(job.sourceId));if(job.independent){chartRanges.set(job.sourceId,{start:job.start,end:job.end});updateAllNavigators(job.start,job.end,job.sourceId);return}dateStart.value=job.start;dateEnd.value=job.end;targetTimeCharts(job).forEach(function(entry){chartRanges.set(entry[0],{start:job.start,end:job.end})});updateAllNavigators(job.start,job.end,job.sourceId)}
