function flushPreviewRange(){previewFrame=null;if(previewApplying||!previewRange)return;const job=previewRange;previewRange=null;const entry=timeCharts.find(function(item){return item[0]===job.sourceId});if(!entry)return;const chart=document.getElementById(entry[0]),update={};update[entry[1]+'.range']=[job.start,job.end];update[entry[1]+'.autorange']=false;if(chart.id==='strategy-diagnostic-2')update['xaxis.range']=[job.start,job.end];previewApplying=true;syncingDates=true;previewPromise=Plotly.relayout(chart,update).finally(function(){previewApplying=false;syncingDates=false;if(previewRange&&previewFrame===null)previewFrame=requestAnimationFrame(flushPreviewRange)})}
