document.querySelectorAll('.tab-button[data-panel]').forEach(function(button){button.addEventListener('click',function(){const group=button.closest('.section');group.querySelectorAll('.tab-button[data-panel]').forEach(function(item){item.classList.toggle('active',item===button)});group.querySelectorAll('.chart-panel').forEach(function(panel){panel.hidden=panel.id!==button.dataset.panel});const returnsTools=group.querySelector('#returns-mode-tools');if(returnsTools)returnsTools.hidden=button.dataset.panel!=='return-panel';const panel=document.getElementById(button.dataset.panel),chart=panel?panel.querySelector('.plotly-graph-div'):null,nav=panel?panel.querySelector('.date-navigator'):null;if(chart)requestAnimationFrame(function(){Plotly.Plots.resize(chart);if(nav)renderNavigatorTicks(nav);const range=chartRanges.get(chart.id)||{start:dateStart.value,end:dateEnd.value};setDateRange(range.start,range.end,chart.id)})})});
document.querySelectorAll('.axis-button[data-returns-mode]').forEach(function(button){button.addEventListener('click',function(){const nextLog=button.dataset.returnsMode==='log';if(nextLog===returnsLogScale)return;returnsLogScale=nextLog;document.querySelectorAll('.axis-button[data-returns-mode]').forEach(function(item){const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',String(active))});const chart=document.getElementById('returns-chart'),range=chartRanges.get('returns-chart')||{start:dateStart.value,end:dateEnd.value};clearHoverPoint(chart);rebaseChart('returns-chart',range.start,'returns').then(function(){return Promise.all([updateActionMarkers('returns-chart'),updateMddMarkers('returns-chart',range.start,range.end,'returns')])}).then(function(){return Plotly.relayout(chart,yAxisUpdates(chart,range.start,range.end))}).then(function(){return syncMddMarkerVisibility(chart)})})});
document.querySelectorAll('.summary-tab').forEach(function(button){button.addEventListener('click',function(){document.querySelectorAll('.summary-tab').forEach(function(item){item.classList.toggle('active',item===button)});document.querySelectorAll('.summary-panel').forEach(function(panel){panel.hidden=panel.id!==button.dataset.summary})})});
document.querySelectorAll('[data-window]').forEach(function(button){button.addEventListener('click',function(){document.querySelectorAll('[data-window]').forEach(function(item){item.classList.toggle('active',item===button)});if(button.dataset.window==='all'){setDateRange(dataMin,dataMax,null);return}const endDate=new Date(dataMax+'T00:00:00');endDate.setMonth(endDate.getMonth()-Number(button.dataset.window));setDateRange(endDate.toISOString().slice(0,10),dataMax,null)})});
